mapper.select:

AND dr.line_id=#{lineId}
AND dr.product_id=#{productId}
AND dr.category_id=#{categoryId}
AND dr.level=#{level}
AND dr.result=#{result}
AND dr.shift=#{shift}
AND dr.detect_time >= #{startTime}
AND dr.detect_time <= #{endTime}
ORDER BY dr.detect_time DESC


AND dr.batch_no=#{batchNo}
AND dr.line_id=#{lineId}
ORDER BY dr.detect_time DESC

SELECT dc.name AS name, COUNT(*) AS value
FROM defect_record dr JOIN defect_category dc ON dr.category_id=dc.id
WHERE dr.is_deleted=0 AND dr.result=0
AND DATE(dr.detect_time) >= #{startDate}
AND DATE(dr.detect_time) <= #{endDate}
GROUP BY dc.id,dc.name ORDER BY value DESC LIMIT 10

SELECT

    DATE_FORMAT(detect_time,'%x-%v')
    DATE_FORMAT(detect_time,'%Y-%m')
    DATE(detect_time)

AS date, COUNT(*) AS totalCount, ROUND(SUM(result)/COUNT(*),4) AS qualifiedRate
FROM defect_record WHERE is_deleted=0
AND DATE(detect_time) >= #{startDate}
AND DATE(detect_time) <= #{endDate}
AND line_id=#{lineId}
AND category_id=#{categoryId}
GROUP BY 1 ORDER BY 1 ASC
